//! `POST /api/invoke/:cmd` — runs the very same `#[tauri::command]`
//! functions the desktop app registers in lib.rs, via the
//! `__web_cmd_<name>` wrappers generated by the shim macro.

use axum::body::Bytes;
use axum::extract::{Path, State};
use axum::http::StatusCode;
use axum::response::{IntoResponse, Response};
use axum::Json;
use serde_json::{json, Value};
use tauri::AppHandle;

use super::AppState;

type Handler = fn(AppHandle, Value) -> tauri::__private::BoxFuture<'static, tauri::__private::InvokeResult>;

use crate as root;
use crate::agent::skills as agent_skills;
use crate::commands::{
    claude_cli, codex_cli, external_search, extract_images, file_history, file_sync, fs, project,
    project_maintenance, search, vectorstore,
};

/// Mirror of `tauri::generate_handler![...]` in src-tauri/src/lib.rs.
/// When upstream adds a command, add it here too (the build fails loudly
/// if a listed command disappears).
macro_rules! command_table {
    ($( $m:ident => [ $($name:ident),* $(,)? ] )*) => { paste::paste! {
        fn lookup(name: &str) -> Option<Handler> {
            match name {
                $($( stringify!($name) => Some($m::[<__web_cmd_ $name>] as Handler), )*)*
                _ => None,
            }
        }
        #[allow(dead_code)]
        pub const COMMANDS: &[&str] = &[$($(stringify!($name)),*),*];
    }};
}

