/// Commands that make no sense on a headless server (they would spawn
/// local CLIs or talk to desktop-only services).
fn disabled_reason(name: &str, st: &AppState) -> Option<&'static str> {
    match name {
        "claude_cli_spawn" | "codex_cli_spawn" if !st.cfg.allow_cli => Some(
            "Claude Code / Codex CLI transports are disabled in the web version (set LLM_WIKI_ALLOW_CLI=1 and install the CLI in the container to enable).",
        ),
        "anytxt_search" => Some("AnyTXT desktop search is not available in the web version."),
        "open_project_folder" | "open_path_in_project" => {
            Some("Opening folders on the server desktop is not available in the web version.")
        }
        _ => None,
    }
}

/// Synthetic results for detection commands, so the UI shows the feature
/// as unavailable instead of erroring.
fn synthetic(name: &str, st: &AppState) -> Option<Value> {
    match name {
        "claude_cli_detect" | "codex_cli_detect" if !st.cfg.allow_cli => Some(json!({
            "installed": false,
            "version": null,
            "path": null,
            "error": "Not available in the web version",
        })),
        "api_server_status" if !st.cfg.enable_api_server => Some(json!("disabled")),
        _ => None,
    }
}

pub async fn handle_invoke(
    State(st): State<AppState>,
    Path(cmd): Path<String>,
    body: Bytes,
) -> Response {
    let args: Value = if body.is_empty() {
        json!({})
    } else {
        match serde_json::from_slice(&body) {
            Ok(v) => v,
            Err(e) => return error(StatusCode::BAD_REQUEST, format!("invalid JSON args: {e}")),
        }
    };
    let Some(handler) = lookup(&cmd) else {
        return error(StatusCode::NOT_FOUND, format!("Command {cmd} not found"));
    };
    if let Some(v) = synthetic(&cmd, &st) {
        return Json(v).into_response();
    }
    if let Some(reason) = disabled_reason(&cmd, &st) {
        return error(StatusCode::BAD_REQUEST, reason.to_string());
    }
    if let Err(e) = super::paths::check_args(&st.cfg.data_dir, &args) {
        return error(StatusCode::FORBIDDEN, e);
    }
    // Run on its own task so a panic in a parser cannot take the
    // connection handler down with it.
    let fut = handler(st.app.clone(), args);
    match tokio::spawn(fut).await {
        Ok(Ok(v)) => Json(v).into_response(),
        Ok(Err(e)) => (StatusCode::BAD_REQUEST, Json(json!({ "error": e }))).into_response(),
        Err(join) => error(
            StatusCode::INTERNAL_SERVER_ERROR,
            tauri::__private::join_error(join).as_str().unwrap_or("panic").to_string(),
        ),
    }
}

fn error(code: StatusCode, msg: String) -> Response {
    (code, Json(json!({ "error": msg }))).into_response()
}
